  public synchronized JsonObject status(String actor,JsonObject payload,boolean pin)throws Exception{
    String entryId=uuid(text(payload,"id",36));mutate(c->{lockSettings(c);JsonObject old=lockedEntry(c,entryId);expected(old,payload);if(pin){boolean value=strictBool(payload,"pinned");if(truth(old.get("pinned"))==value)return false;update(c,"UPDATE ph_entries SET pinned=?,revision=revision+1,updated_at=? WHERE id=?",value,System.currentTimeMillis(),entryId);}else{String status=text(payload,"status",16);if(!Set.of("published","withdrawn").contains(status))throw new IllegalArgumentException("发布状态无效");if(text(old,"status",16).equals(status))return false;update(c,"UPDATE ph_entries SET status=?,published_at=IF(?='published' AND published_at IS NULL,?,published_at),updated_at=?,revision=revision+1 WHERE id=?",status,status,System.currentTimeMillis(),System.currentTimeMillis(),entryId);}audit(c,actor,pin?"PLAYERHUB_ENTRY_PIN":"PLAYERHUB_ENTRY_STATUS",payload);return true;});return stamp(obj("entry",read("",null,entryId,0,0,"all",new JsonObject()).get("entry")));
  }
  public synchronized JsonObject deleteEntry(String actor,JsonObject payload)throws Exception{String entryId=uuid(text(payload,"id",36));mutate(c->{lockSettings(c);JsonObject old=lockedEntry(c,entryId);expected(old,payload);if(!text(old,"title",80).equals(text(payload,"confirmTitle",80)))throw new IllegalStateException("请输入已保存的完整日志标题");for(String table:List.of("ph_likes","ph_comments","ph_replies","ph_operations"))update(c,"DELETE FROM "+table+" WHERE entry_id=?",entryId);update(c,"DELETE FROM ph_entries WHERE id=?",entryId);audit(c,actor,"PLAYERHUB_ENTRY_DELETE",obj("id",entryId,"title",text(old,"title",80)));return true;});return stamp(obj("ok",true));}
  public synchronized JsonObject saveSettings(String actor,JsonObject payload)throws Exception{
    boolean updates=strictBool(payload,"updatesEnabled"),likes=strictBool(payload,"likesEnabled"),comments=strictBool(payload,"commentsEnabled");long limit=number(payload,"commentLimit",-1,50,2000),cooldown=number(payload,"commentCooldown",-1,0,300);if(limit<50||cooldown<0)throw new IllegalArgumentException("留言限制必填");mutate(c->{lockSettings(c);JsonObject old=settings(c);expected(old,payload);if(old.get("updatesEnabled").getAsBoolean()==updates&&old.get("likesEnabled").getAsBoolean()==likes&&old.get("commentsEnabled").getAsBoolean()==comments&&old.get("commentLimit").getAsInt()==limit&&old.get("commentCooldown").getAsInt()==cooldown)return false;update(c,"UPDATE ph_settings SET updates_enabled=?,likes_enabled=?,comments_enabled=?,comment_limit=?,comment_cooldown=?,revision=revision+1 WHERE id=1",updates,likes,comments,limit,cooldown);audit(c,actor,"PLAYERHUB_SETTINGS",payload);return true;});try(Connection c=store.open()){return stamp(obj("settings",settings(c)));}
  }
  public synchronized JsonObject visibility(String actor,JsonObject payload)throws Exception{String packId=uuid(text(payload,"packId",36));boolean visible=strictBool(payload,"visible");mutate(c->{lockSettings(c);JsonObject old=pack(c,packId);expected(old,payload);if(old.get("visible").getAsBoolean()==visible)return false;update(c,"UPDATE ph_packs SET visible=?,revision=revision+1 WHERE id=?",visible,packId);audit(c,actor,"PLAYERHUB_PACK_VISIBILITY",payload);return true;});try(Connection c=store.open()){return stamp(obj("pack",pack(c,packId)));}}
  public synchronized JsonObject like(String instance,String player,JsonObject payload)throws Exception{String entryId=uuid(text(payload,"id",36));boolean liked=strictBool(payload,"liked");mutate(c->{lockSettings(c);profile(c,player);playerEnabled(c);entry(c,instance,player,entryId,false);if(!settings(c).get("likesEnabled").getAsBoolean())throw new IllegalStateException("点赞暂未开放");int changed=liked?update(c,"INSERT IGNORE INTO ph_likes(entry_id,player_uuid,created_at) VALUES(?,?,?)",entryId,player,System.currentTimeMillis()):update(c,"DELETE FROM ph_likes WHERE entry_id=? AND player_uuid=?",entryId,player);if(changed>0)playerRevision(c,player);return changed>0;});try(Connection c=store.open()){return stamp(obj("id",entryId,"liked",liked,"likesCount",one(c,"SELECT COUNT(*) n FROM ph_likes WHERE entry_id=?",entryId).get("n")));}}
  private static String commentText(JsonObject payload,int max){String value=text(payload,"text",2000).strip();if(value.isEmpty()||value.codePointCount(0,value.length())>max)throw new IllegalArgumentException("留言须为1至"+max+"字");return value;}
  private static boolean duplicate(Connection c,String player,String operation,String kind,String hash)throws Exception{var old=rows(c,"SELECT kind,request_hash FROM ph_operations WHERE player_uuid=? AND operation_id=? FOR UPDATE",player,operation);if(old.isEmpty())return false;if(!text(old.get(0),"kind",16).equals(kind)||!text(old.get(0),"request_hash",64).equals(hash))throw new IllegalStateException("同一操作标识不能用于不同留言");return true;}
  public synchronized JsonObject comment(String instance,String player,JsonObject payload)throws Exception{
    String entryId=uuid(text(payload,"id",36)),operation=uuid(text(payload,"operationId",36));mutate(c->{lockSettings(c);profile(c,player);playerEnabled(c);entry(c,instance,player,entryId,false);JsonObject settings=settings(c);String text=commentText(payload,settings.get("commentLimit").getAsInt()),hash=digest(entryId+"\n"+text);if(duplicate(c,player,operation,"comment",hash))return false;if(!settings.get("commentsEnabled").getAsBoolean())throw new IllegalStateException("新留言暂未开放");long now=System.currentTimeMillis(),cooldown=settings.get("commentCooldown").getAsLong()*1000;var prior=rows(c,"SELECT created_at FROM ph_operations WHERE player_uuid=? AND kind='comment' ORDER BY created_at DESC LIMIT 1",player);if(!prior.isEmpty()&&now-prior.get(0).get("created_at").getAsLong()<cooldown)throw new IllegalStateException("发送过快，请稍后再试");String comment=UUID.randomUUID().toString();update(c,"INSERT INTO ph_comments(id,entry_id,author_uuid,text,created_at) VALUES(?,?,?,?,?)",comment,entryId,player,text,now);update(c,"INSERT INTO ph_operations(player_uuid,operation_id,owner_uuid,kind,request_hash,entry_id,resource_id,created_at) VALUES(?,?,?,'comment',?,?,?,?)",player,operation,player,hash,entryId,comment,now);playerRevision(c,player);return true;});return read(instance,player,entryId,0,0,"all",new JsonObject());
  }
  public synchronized JsonObject reply(String actor,String adminName,JsonObject payload)throws Exception{
    String entryId=uuid(text(payload,"id",36)),commentId=uuid(text(payload,"commentId",36)),operation=uuid(text(payload,"operationId",36));mutate(c->{lockSettings(c);lockedEntry(c,entryId);String text=commentText(payload,2000),hash=digest(entryId+"\n"+commentId+"\n"+text);if(duplicate(c,actor,operation,"reply",hash))return false;JsonObject comment=one(c,"SELECT author_uuid FROM ph_comments WHERE id=? AND entry_id=? FOR UPDATE",commentId,entryId);String owner=text(comment,"author_uuid",36),reply=UUID.randomUUID().toString();long now=System.currentTimeMillis();update(c,"INSERT INTO ph_replies(id,entry_id,comment_id,owner_uuid,admin_uuid,admin_name,text,created_at) VALUES(?,?,?,?,?,?,?,?)",reply,entryId,commentId,owner,actor,adminName,text,now);update(c,"INSERT INTO ph_operations(player_uuid,operation_id,owner_uuid,kind,request_hash,entry_id,resource_id,created_at) VALUES(?,?,?,'reply',?,?,?,?)",actor,operation,owner,hash,entryId,reply,now);playerRevision(c,owner);return true;});return read("",null,entryId,0,0,"all",new JsonObject());
  }
  public synchronized JsonObject deleteComment(String instance,String player,String actor,JsonObject payload)throws Exception{String entryId=uuid(text(payload,"id",36)),commentId=uuid(text(payload,"commentId",36));mutate(c->{lockSettings(c);if(player!=null){profile(c,player);playerEnabled(c);}entry(c,instance,player,entryId,false);var selected=rows(c,"SELECT author_uuid FROM ph_comments WHERE id=? AND entry_id=? FOR UPDATE",commentId,entryId);if(selected.isEmpty())return false;String author=text(selected.get(0),"author_uuid",36);if(player!=null&&!author.equals(player))throw new SecurityException("只能删除自己的留言");update(c,"DELETE FROM ph_replies WHERE comment_id=?",commentId);update(c,"DELETE FROM ph_comments WHERE id=?",commentId);playerRevision(c,author);if(player==null)audit(c,actor,"PLAYERHUB_COMMENT_DELETE",obj("entryId",entryId,"commentId",commentId));return true;});return read(instance,player,entryId,0,0,"all",new JsonObject());}
  public synchronized JsonObject player(String instance,String player,String action,JsonObject payload)throws Exception{
    uuid(player);try(Connection c=store.open()){profile(c,player);}return switch(action){case "snapshot"->snapshot(instance,player);case "packs"->packs(instance,player,(int)number(payload,"page",0,0,100000));case "list"->list(instance,player,stringQuery(payload,Set.of("packId","page","search")));case "read"->{JsonObject pages=object(payload,"replyPages");if(pages.size()>12)throw new IllegalArgumentException("回复分页数量过多");yield read(instance,player,uuid(text(payload,"id",36)),(int)number(payload,"commentsPage",0,0,100000),0,"all",pages);}case "like"->like(instance,player,payload);case "comment"->comment(instance,player,payload);case "deleteComment"->deleteComment(instance,player,player,payload);default->throw new IllegalArgumentException("玩家更新日志操作未注册");};
  }
  private static Map<String,String> stringQuery(JsonObject payload,Set<String> keys){Map<String,String> query=new HashMap<>();for(String key:keys)if(payload.has(key)&&!payload.get(key).isJsonNull())query.put(key,payload.get(key).getAsString());return query;}
  public synchronized JsonObject admin(String method,String path,JsonObject payload,Map<String,String> query,String actor,String adminName)throws Exception{
    boolean post=method.equals("POST");if(!post&&!method.equals("GET"))throw new IllegalArgumentException("仅支持 GET / POST");
    if(!post)return switch(path){case "/state"->snapshot("",null);case "/packs"->packs("",null,integer(query,"page",0,0,100000));case "/entries"->list("",null,query);case "/entry"->read("",null,uuid(query.getOrDefault("id","")),integer(query,"commentsPage",0,0,100000),integer(query,"likesPage",0,0,100000),query.getOrDefault("commentsFilter","all"),new JsonObject());case "/replies"->adminReplies(uuid(query.getOrDefault("id","")),uuid(query.getOrDefault("commentId","")),integer(query,"page",0,0,100000));default->throw new IllegalArgumentException("更新日志接口不存在");};
    return switch(path){case "/entry/save"->save(actor,payload);case "/entry/status"->status(actor,payload,false);case "/entry/pin"->status(actor,payload,true);case "/entry/delete"->deleteEntry(actor,payload);case "/settings"->saveSettings(actor,payload);case "/pack/visibility"->visibility(actor,payload);case "/comment/reply"->reply(actor,adminName,payload);case "/comment/delete"->deleteComment("",null,actor,payload);default->throw new IllegalArgumentException("更新日志接口不存在");};
  }
  /** Strict ProseMirror subset shared with the approved editor. Unknown nodes/attributes are rejected. */
  private static JsonObject document(JsonElement raw){if(!raw.isJsonObject()||raw.toString().getBytes(StandardCharsets.UTF_8).length>160000)throw new IllegalArgumentException("正文文档无效或过大");int[] count={0};JsonObject doc=node(raw.getAsJsonObject(),null,0,count);if(!text(doc,"type",16).equals("doc"))throw new IllegalArgumentException("正文须为doc文档");return doc;}
  private static JsonObject node(JsonObject in,String parent,int depth,int[] count){
    if(depth>16||++count[0]>4000)throw new IllegalArgumentException("正文结构过于复杂");String type=text(in,"type",16);if(!Set.of("doc","paragraph","heading","bulletList","listItem","hardBreak","text").contains(type))throw new IllegalArgumentException("正文包含不支持的节点");
    if(parent==null&&!type.equals("doc")||parent!=null&&type.equals("doc")||Set.of("paragraph","heading").contains(Objects.toString(parent,""))&&!Set.of("text","hardBreak").contains(type)||"bulletList".equals(parent)&&!type.equals("listItem")||"listItem".equals(parent)&&!Set.of("paragraph","bulletList").contains(type)||"doc".equals(parent)&&!Set.of("paragraph","heading","bulletList").contains(type))throw new IllegalArgumentException("正文节点层级无效");
    Set<String> keys=switch(type){case "text"->Set.of("type","text","marks");case "heading"->Set.of("type","content","attrs");case "hardBreak"->Set.of("type");default->Set.of("type","content");};if(!keys.containsAll(in.keySet()))throw new IllegalArgumentException("正文包含不支持的属性");JsonObject out=obj("type",type);
    if(type.equals("text")){String text=text(in,"text",20000);if(text.isEmpty())throw new IllegalArgumentException("正文文本节点为空");out.addProperty("text",text);if(in.has("marks")){if(!in.get("marks").isJsonArray())throw new IllegalArgumentException("正文标记无效");JsonArray marks=array(in,"marks",1);for(JsonElement mark:marks)if(!mark.isJsonObject()||!mark.getAsJsonObject().keySet().equals(Set.of("type"))||!text(mark.getAsJsonObject(),"type",16).equals("bold"))throw new IllegalArgumentException("正文仅支持加粗标记");if(!marks.isEmpty())out.add("marks",marks.deepCopy());}}
    if(type.equals("heading")){JsonObject attrs=object(in,"attrs");if(!attrs.keySet().equals(Set.of("level"))||number(attrs,"level",-1,3,3)!=3)throw new IllegalArgumentException("正文仅支持三级标题");out.add("attrs",obj("level",3));}
    if(in.has("content")){if(!in.get("content").isJsonArray())throw new IllegalArgumentException("正文子节点无效");JsonArray children=array(in,"content",4000),clean=new JsonArray();for(JsonElement child:children){if(!child.isJsonObject())throw new IllegalArgumentException("正文节点无效");clean.add(node(child.getAsJsonObject(),type,depth+1,count));}if(!clean.isEmpty())out.add("content",clean);}return out;
  }
  private static String documentText(JsonObject node){String type=text(node,"type",16);if(type.equals("text"))return text(node,"text",20000);if(type.equals("hardBreak"))return "\n";List<String> pieces=new ArrayList<>();for(JsonElement child:array(node,"content",4000))pieces.add(documentText(child.getAsJsonObject()));return String.join(Set.of("doc","bulletList","listItem").contains(type)?"\n":"",pieces);}
